_LONGEST_CODE = max(len(code) for code in NATIONAL_LENGTHS)


def split_international(digits: str) -> tuple[str, str] | None:
    """Split the digits after a ``+`` into (calling code, national number).

    None when they start with no assigned code, or the national number is
    shorter or longer than that country's numbers can be.
    """
    for size in range(1, _LONGEST_CODE + 1):
        code = digits[:size]
        lengths = NATIONAL_LENGTHS.get(code)
        if lengths is not None:
            national = digits[size:]
            if lengths[0] <= len(national) <= lengths[1]:
                return code, national
            return None
    return None
